    private function board(string $who,string $scope,int $offset,array $me):array{if(!in_array($scope,['friends','global','gym'],true))$this->bad(400,'Clasificación no válida.');if($scope==='gym'&&!$me['training_place'])return['entries'=>[],'next'=>null,'total'=>0,'me'=>null,'nextRival'=>null,'gap'=>null,'needsLocation'=>true,'location'=>''];$all=[];foreach($this->q('SELECT p.*,g.payload FROM community_profiles p JOIN community_progress g ON g.user_id=p.user_id WHERE p.ranking_public=1')->fetchAll() as $p){if($this->blocked($who,$p['user_id']))continue;if($scope==='friends'&&$p['user_id']!==$who&&!$this->connected($who,$p['user_id']))continue;if($scope==='gym'&&$this->gymKey($p['training_place'])!==$this->gymKey($me['training_place']))continue;$d=json_decode($p['payload'],true);if(!is_array($d)||empty($d['pointsRankingEligible'])||!is_numeric($d['points']??null))continue;$all[]=['id'=>$p['user_id'],'handle'=>$p['handle'],'name'=>$p['name'],'avatar'=>$p['avatar'],'points'=>(float)$d['points'],'coverage'=>(int)($d['pointsCoverage']??0),'reliability'=>(int)($d['pointsReliability']??0)];}usort($all,fn($a,$b)=>$b['points']<=>$a['points']?:strcmp($a['handle'],$b['handle']));foreach($all as $i=>&$e)$e['rank']=$i+1;unset($e);$mine=array_values(array_filter($all,fn($e)=>$e['id']===$who))[0]??null;$rival=$mine?$all[$mine['rank']]??null:null;return['entries'=>array_slice($all,$offset,20),'next'=>$offset+20<count($all)?$offset+20:null,'total'=>count($all),'me'=>$mine,'nextRival'=>$rival,'gap'=>$mine&&$rival?round($rival['points']-$mine['points'],1):null,'needsLocation'=>false,'location'=>$scope==='gym'?$me['training_place']:''];}
