        if(preg_match('#^/routines/([a-f0-9]{32})$#i',$path,$m)&&$method==='GET'){$p=$this->profile($m[1],'');if(!($m[1]===$who||(bool)$p['routine_public']||$this->connected($who,$m[1])))$this->bad(403,'Esta rutina es privada o solo está disponible entre seguidores mutuos.');$r=$this->q('SELECT payload,updated FROM community_routines WHERE user_id=?',[$m[1]])->fetch();if(!$r)$this->bad(404,'Rutina no disponible.');return['id'=>$m[1],'owner'=>['handle'=>$p['handle'],'name'=>$p['name']],'routine'=>json_decode($r['payload'],true),'updated'=>$r['updated']];}
        if(preg_match('#^/profiles/([a-f0-9]{32})$#i',$path,$m)&&$method==='GET'){if($this->blocked($who,$m[1]))$this->bad(404,'Perfil no encontrado.');return$this->view($this->profile($m[1],''),$who);}
        $this->bad(404,'Ruta de Comunidad no disponible.');
